// Number::multiply step 6 and the sign of an exact zero product.
// Literal step 6: 𝔽(0) is +0, so 1/(+0 * -5) is +Infinity.
// IEEE 754-2019 (the clause's description): -0, so -Infinity.
if (typeof print === "undefined") globalThis.print = console.log;
print(String(1 / (0 * -5)));   // +0 × -5
print(String(1 / (-5 * 0)));   // -5 × +0
print(String(1 / (0 * 5)));    // +0 × 5 (both readings: Infinity)
print(String(Object.is(-5 * 0, -0)));

// Flags: --bundle

// JS_BUNDLE_MODULE:a.mjs
import "./b.mjs";
import "./c.mjs";
globalThis.print("a runs");
// JS_BUNDLE_MODULE:b.mjs
if (typeof print === "undefined") globalThis.print = console.log;
print("b starts");
await 0;
print("b ends");
// JS_BUNDLE_MODULE:c.mjs
if (typeof print === "undefined") globalThis.print = console.log;
print("c throws");
throw "c-error";
// JS_BUNDLE_MODULE_ENTRYPOINT:main.mjs
// GatherAvailableAncestors 1.a reads a.[[CycleRoot]] of a module a whose
// synchronous evaluation threw (Evaluate 9.a never sets [[CycleRoot]]).
// a.mjs imports b.mjs (top-level await) and then c.mjs (throws).
if (typeof print === "undefined") globalThis.print = console.log;
import("./a.mjs").then(
  function () { print("a fulfilled"); },
  function (e) { print("a rejected: " + e); })
  .then(function () { return import("./b.mjs"); })
  .then(function () { print("b fulfilled"); }, function (e) { print("b rejected: " + e); });

// BuiltinCallOrConstruct 10.b.iii and AsyncBlockStart 1.f: the fulfilment
// value of a built-in async function. Literal text: undefined.
if (typeof print === "undefined") globalThis.print = console.log;
Array.fromAsync([1, 2]).then(function (v) {
  print("fromAsync fulfils with " + JSON.stringify(v));
});

// Flags: --bundle

// JS_BUNDLE_MODULE:m.mjs
if (typeof print === "undefined") globalThis.print = console.log;
await using a = { async [Symbol.asyncDispose]() { print("dispose a"); } };
using b = { [Symbol.dispose]() { print("dispose b"); } };
await null;
print("end of module body");
// JS_BUNDLE_MODULE_ENTRYPOINT:main.mjs
// ExecuteModule 4.b: a module with top-level await never disposes the
// resources of its top-level `using` / `await using` declarations.
if (typeof print === "undefined") globalThis.print = console.log;
import("./m.mjs").then(function () { print("evaluation promise fulfilled"); },
                       function (e) { print("rejected: " + e); });

// ParseText returns "a List of one or more SyntaxError objects". No
// algorithm reads the List's objects: PerformEval throws its own SyntaxError
// (step 11.b), from the current realm.
if (typeof print === "undefined") globalThis.print = console.log;
try { eval("var x = ;"); } catch (e) { print(e instanceof SyntaxError); }
try { Function("a", "return a +;"); } catch (e) { print(e instanceof SyntaxError); }
try { new RegExp("("); } catch (e) { print(e instanceof SyntaxError); }

// DoWait 28.a–31: a synchronous Atomics.wait that times out. Literal text:
// it returns "ok" (the [[Result]] of step 26) and its Waiter Record stays in
// the WaiterList; the second wait then fails AddWaiter step 2's Assert, and
// Atomics.notify counts a waiter that is not waiting.
// (Needs an agent that can block: node, bun, d8, the SpiderMonkey shell.)
if (typeof print === "undefined") globalThis.print = console.log;
var ia = new Int32Array(new SharedArrayBuffer(4));
print(Atomics.wait(ia, 0, 0, 0));
print(Atomics.wait(ia, 0, 0, 1));
print(Atomics.notify(ia, 0));

// EnqueueAtomicsWaitAsyncTimeoutJob 1.b.ii: "Assert: ℝ(timeOfJobExecution) ≥
// waiterRecord.[[TimeoutTime]]". With a fractional timeout and
// additionalTimeout 0, [[TimeoutTime]] is not a time value; a host whose clock
// has millisecond resolution may run the Job (after "at least" the step 4
// delay) at a time below it.
if (typeof print === "undefined") globalThis.print = console.log;
var ia = new Int32Array(new SharedArrayBuffer(8));
var t0 = Date.now();
var r = Atomics.waitAsync(ia, 0, 0, 0.7);
print(r.async);
r.value.then(function (v) { print(v + ", elapsed ≥ 0: " + (Date.now() - t0 >= 0)); });
// (node ends the process when only an Atomics.waitAsync timeout is pending)
if (typeof setTimeout === "function") setTimeout(function () {}, 50);

// UTC ( t ) step 4.a with a large finite local time t: MakeDay (in
// GetUTCEpochNanoseconds step 1) finds no time value on the month's first
// day and returns NaN, so the Assert of GetUTCEpochNanoseconds step 4 fails.
// First, MakeDay step 8's "finite time value": any finite integral Number, or
// one in the range a time value supports (8.64e15)? 1 January 275761 is
// outside the range, but 256 days before it is inside.
if (typeof print === "undefined") globalThis.print = console.log;
print(Date.UTC(275761, 0, -256));            // range reading: NaN; any-integral reading: 8639987299200000
print(Date.UTC(275760, 8, 13));              // the last time value, either reading
print(new Date(0).setUTCHours(1e21));        // the UTC setter: no UTC(t), NaN
print(new Date(0).setHours(1e21));           // local: UTC(t) with t = 3.6e27
print(new Date(2000, 0, 1, 1e21).getTime()); // the constructor: UTC(t)

// RegExpBuiltinExec with /u and lastIndex on the trailing surrogate of a pair.
// A non-empty match (steps 13.b, 22, 24, 28): the literal text reports index 1
// and a lone trailing surrogate as the match.
// An empty match: match = { [[StartIndex]]: 1, [[EndIndex]]: 0 }, which the
// Match Record table does not allow, and GetMatchString step 1's Assert fails.
if (typeof print === "undefined") globalThis.print = console.log;
var n = /./gu;
n.lastIndex = 1;
var mn = n.exec("\u{1F600}x");
print("non-empty: index " + mn.index + ", match length " + mn[0].length +
  ", first unit " + mn[0].charCodeAt(0).toString(16) + ", lastIndex " + n.lastIndex);
var r = /(?:)/gu;
r.lastIndex = 1;
var m = r.exec("\u{1F600}");
print("empty: index " + m.index + ", match length " + m[0].length + ", lastIndex " + r.lastIndex);
var rd = /(?:)/gud;
rd.lastIndex = 1;
var md = rd.exec("\u{1F600}");
print("indices[0] " + JSON.stringify(md.indices[0]));

// AsyncBlockStart step 4 "Assert: result is unused" against Await step 8
// "Return ? RunCallerContext(empty)": every async function that awaits.
if (typeof print === "undefined") globalThis.print = console.log;
async function f() { await 1; return 2; }
f().then(function (v) { print("f fulfilled with " + v); });

// §9.5 "The Abstract Closure must return a normal completion" against
// NewPromiseReactionJob 1.i "Return ? Call(promiseCapability.[[Resolve]], …)",
// with a capability whose resolve function throws (a species constructor).
// The second reaction has no handler: its Job's realm is null, yet it calls
// the program's resolve function (§9.5: such a job "does not evaluate
// ECMAScript code").
if (typeof print === "undefined") globalThis.print = console.log;
function Bad(executor) {
  executor(function (v) { print("resolve(" + v + ") called; it throws"); throw new Error("boom"); },
           function () {});
}
Bad[Symbol.species] = Bad;
var p = Promise.resolve(1);
p.constructor = Bad;
p.then(function (v) { print("handler " + v); return v; });
var q = Promise.resolve(2);
q.constructor = Bad;
q.then();   // no handler: the Job's realm is null
Promise.resolve(3).then(function () { print("a later Job runs"); });

// Function.prototype.toString step 3: for a built-in function whose
// [[InitialName]] no PropertyName matches, no String has "the syntax of a
// NativeFunction" with that name as its PropertyName portion. A class's
// default constructor is a built-in function (ClassDefinitionEvaluation
// 14.b) named by NamedEvaluation; on a host whose HostHasSourceTextAvailable
// is false, step 3 applies to it.
if (typeof print === "undefined") globalThis.print = console.log;
var o = { ["a b"]: class {} };
print(JSON.stringify(o["a b"].name));
class C { static #x = class {}; static name2() { return C.#x.name; } }
print(JSON.stringify(C.name2()));
var s = { [Symbol("a b")]: class {} };
print(JSON.stringify(s[Object.getOwnPropertySymbols(s)[0]].name));
// With source text available (every engine), step 2 returns the class text:
print(Function.prototype.toString.call(o["a b"]));

// Flags: --bundle

// JS_BUNDLE_MODULE:j.json
{"a": 1}
// JS_BUNDLE_MODULE:other.mjs
import "./probe.mjs";
import k from "./j.json" with { type: "json" };
export { k };
// JS_BUNDLE_MODULE:probe.mjs
import { readJ } from "./main.mjs";
var print = globalThis.print || console.log;
print("probe sees " + JSON.stringify(readJ()));
// JS_BUNDLE_MODULE_ENTRYPOINT:main.mjs
// Link of a Synthetic Module Record: InnerModuleLinking 1.a calls it for each
// importer, and each call gives the module a new environment whose bindings
// are undefined until InnerModuleEvaluation evaluates it again. other.mjs
// imports probe.mjs before j.json, so probe.mjs runs between the two.
if (typeof print === "undefined") globalThis.print = console.log;
import j from "./j.json" with { type: "json" };
export function readJ() { return j; }
print("main sees " + JSON.stringify(j));
import("./other.mjs").then(function () { print("after other: " + JSON.stringify(j)); },
                           function (e) { print("rejected: " + e); });

if (typeof print === "undefined") globalThis.print = console.log;
// AllPrivateIdentifiersValid is checked only for a Script or Module body.
try { new Function("o", "return o.#f"); print("body: no error"); }
catch (e) { print("body: " + e.constructor.name); }
try { new Function("a = {}.#g", ""); print("params: no error"); }
catch (e) { print("params: " + e.constructor.name); }
try { eval("(function (o) { return o.#f; })"); print("eval: no error"); }
catch (e) { print("eval: " + e.constructor.name); }

// IdentityEscape[~UnicodeMode] :: SourceCharacter but not UnicodeIDContinue
// (§22.2.1). Since Unicode 15.1, U+200C (ZWNJ) and U+200D (ZWJ) are
// ID_Continue, so the literal text rejects `\` followed by either of them in
// a pattern without the u or v flag; before Unicode 15.1 it accepted them.
// U+200B and U+200E (not ID_Continue) are the neighbours; `a` (U+0061,
// ID_Continue) is an IdentityEscape only in §B.1.2's grammar, which every
// engine implements. The pattern text is built with fromCharCode: the
// characters are invisible.
if (typeof print === "undefined") globalThis.print = console.log;
for (var cu of [0x200C, 0x200D, 0x200B, 0x200E, 0x61]) {
  var ch = String.fromCharCode(cu), src = "\\" + ch, out = [];
  try { var re = eval("/" + src + "/"); out.push("literal " + (re.source === src && re.test(ch))); }
  catch (e) { out.push("literal " + e.constructor.name); }
  try { out.push("RegExp " + new RegExp(src).test(ch)); }
  catch (e) { out.push("RegExp " + e.constructor.name); }
  try { new RegExp(src, "u"); out.push("u ok"); }
  catch (e) { out.push("u " + e.constructor.name); }
  print("U+" + cu.toString(16).toUpperCase() + ": " + out.join(", "));
}

// CompileToCharSet, UnicodePropertyValueExpression :: LoneUnicodePropertyNameOrValue, step 2 calls
// UnicodeMatchPropertyValue(General_Category, s) before testing s; for a binary property name s its
// Assert (step 2) fails.
if (typeof print === "undefined") globalThis.print = console.log;
var cases = [
  ["/\\p{Lu}/u.test('A')", () => /\p{Lu}/u.test("A")],
  ["/\\p{ASCII}/u.test('a')", () => /\p{ASCII}/u.test("a")],
  ["/\\p{Hex}/u.test('f')", () => /\p{Hex}/u.test("f")],
  ["/\\p{Any}/u.test('\\u{10FFFF}')", () => /\p{Any}/u.test("\u{10FFFF}")],
];
for (var [src, run] of cases) {
  try { print(src + ": " + run()); } catch (e) { print(src + ": " + e.constructor.name); }
}

// §22.2.1.1's modifier early errors are keyed on Atom; under §B.1.2 a pattern without `u` or `v` has an
// ExtendedAtom there, which no early error covers. Each pattern is compiled as a literal (indirect eval)
// and by the RegExp constructor.
if (typeof print === "undefined") globalThis.print = console.log;
var patterns = ["(?ii:a)", "(?-:a)", "(?i-i:a)", "(?i:a)", "(?i-m:a)"];
for (var p of patterns) {
  var lit, ctor;
  try { (0, eval)("/" + p + "/"); lit = "no error"; } catch (e) { lit = e.constructor.name; }
  try { new RegExp(p); ctor = "no error"; } catch (e) { ctor = e.constructor.name; }
  print("/" + p + "/: " + lit + "; new RegExp: " + ctor);
}

// The ObjectLiteral `__proto__` early error asks for the PropName of every PropertyDefinition, and PropName
// has no row for CoverInitializedName. Each source is parsed as a Script (indirect eval).
if (typeof print === "undefined") globalThis.print = console.log;
var sources = ["({a = 1});", "({__proto__: 1, __proto__ = 2});", "({a = 1} = {});"];
for (var s of sources) {
  try { (0, eval)(s); print(JSON.stringify(s) + ": no error"); }
  catch (e) { print(JSON.stringify(s) + ": " + e.constructor.name); }
}

// SortIndexedProperties: a <C b means ℝ(comparator(a, b)) < 0, and ℝ(±∞) is not defined, so a comparator
// that returns ±∞ is neither consistent nor inconsistent by the definition.
if (typeof print === "undefined") globalThis.print = console.log;
print([3, 1, 2].sort((a, b) => a < b ? -Infinity : a > b ? Infinity : 0).join());
print([5, 3, 4, 1, 2].sort((a, b) => (a - b) * Infinity).join());
print(["b", "a", "c"].sort((a, b) => a < b ? -Infinity : a > b ? Infinity : 0).join());

// Identifier early errors: "the StringValue of IdentifierName is the StringValue of any ReservedWord except
// for yield or await", and StringValue has no row for ReservedWord. Each source is parsed as a Script.
if (typeof print === "undefined") globalThis.print = console.log;
var sources = ["var \\u0069f = 1;", "var i\\u0066 = 1;", "var \\u{63}lass = 1;", "var \\u0079ield = 1;",
               "var \\u0061wait = 1;", "var \\u0069g = 1;"];
for (var s of sources) {
  try { (0, eval)(s); print(s + ": no error"); }
  catch (e) { print(s + ": " + e.constructor.name); }
}

// CreateIntrinsics step 2 passes _async_ where CreateBuiltinFunction takes _prefix_, and passes no _prefix_.
if (typeof print === "undefined") globalThis.print = console.log;
print(Object.getOwnPropertyDescriptor(Map.prototype, "size").get.name);
print(Object.getOwnPropertyDescriptor(RegExp.prototype, "flags").get.name);
var p = Array.fromAsync([1, 2]);
print(Object.prototype.toString.call(p));
p.then(function (v) { print("fromAsync fulfils with " + JSON.stringify(v)); });

// Contains (§8.5.1) has no row for UnaryExpression :
// CoverAwaitExpressionAndAwaitUsingDeclarationHead, the production an `await`
// expression parses as, so literally no Parse Node contains an
// AwaitExpression and the rules "FormalParameters Contains AwaitExpression"
// never apply. Each source is evaluated as a Script (indirect eval) or by the
// AsyncFunction constructor; test262 expects a SyntaxError for the first six
// and none for the last three.
if (typeof print === "undefined") globalThis.print = console.log;
var AsyncFunction = (async function () {}).constructor;
var cases = [
  ["async function f(x = await 1) {}", () => (0, eval)("async function f(x = await 1) {}")],
  ["(async function* (x = await 1) {})", () => (0, eval)("(async function* (x = await 1) {})")],
  ["({ async m(x = await 1) {} })", () => (0, eval)("({ async m(x = await 1) {} })")],
  ["({ async *m(x = await 1) {} })", () => (0, eval)("({ async *m(x = await 1) {} })")],
  ["async function g() { async (x = await 1) => 0; }", () => (0, eval)("async function g() { async (x = await 1) => 0; }")],
  ["AsyncFunction('x = await 1', '')", () => AsyncFunction("x = await 1", "")],
  ["async function h() { await 1; }", () => (0, eval)("async function h() { await 1; }")],
  ["async function k(x = function () { var await; }) {}", () => (0, eval)("async function k(x = function () { var await; }) {}")],
  ["(async function () { class C { static { } } })", () => (0, eval)("(async function () { class C { static { } } })")],
];
for (var [src, run] of cases) {
  try { run(); print(src + ": no error"); }
  catch (e) { print(src + ": " + e.constructor.name); }
}

// IsLabelledFunction(stmt) takes a Statement node; step 1 asks whether it "is a LabelledStatement" and step 2
// takes its LabelledItem, a grandchild. Each source is parsed as a Script (indirect eval).
if (typeof print === "undefined") globalThis.print = console.log;
var sources = ["if (1) l: function f() {}", "while (0) l: function f() {}",
               "if (0) ; else a: b: function g() {}", "while (0) l: m: x;", "l: function h() {}"];
for (var s of sources) {
  try { (0, eval)(s); print(s + ": no error"); }
  catch (e) { print(s + ": " + e.constructor.name); }
}

// String.prototype.split step 10.d passes a List of code units to CreateArrayFromList, which takes a List
// of ECMAScript language values.
if (typeof print === "undefined") globalThis.print = console.log;
var a = "ab".split("");
print(a.length + " " + typeof a[1] + " " + JSON.stringify(a));
print(new String(" ").split("")[0] === " ");
print(JSON.stringify("\u{1F600}".split("")));

// OrdinarySetWithOwnDescriptor 2.d.i asserts that the receiver "does not currently have" the property right
// after a Proxy receiver's trap said undefined for a property its target has.
if (typeof print === "undefined") globalThis.print = console.log;
var t = { x: 1 };
var p = new Proxy(t, { getOwnPropertyDescriptor() { return undefined; } });
print(Reflect.set({}, "x", 5, p));
print(t.x);

// Each source has a cover that does not cover what an early error rule says it must; the
// other rules of the same and enclosing productions read static semantics through the cover.
if (typeof print === "undefined") globalThis.print = console.log;
var sources = [
  "([...x = []]) => {};",
  "([...x, y]) => {};",
  "(a, ...b,) => {};",
  "async (...x = []) => {};",
  "async\n(foo) => {};",
  "(x) => {};",
];
for (var s of sources) {
  try {
    (0, eval)(s);
    print(JSON.stringify(s) + ": no error");
  } catch (e) {
    print(JSON.stringify(s) + ": " + e.constructor.name);
  }
}

// §B.1.2: "each alternative is considered only if previous production alternatives do not match", and
// AtomEscape's DecimalEscape "only if the CapturingGroupNumber of DecimalEscape is ≤
// CountLeftCapturingParensWithin(the Pattern containing DecimalEscape)". Each pattern is compiled with no
// flags; the string is matched against it.
if (typeof print === "undefined") globalThis.print = console.log;
var cases = [["a{1}", "a"], ["\\b*", ""], ["a\\b?", "ab"], ["\\x4", "x4"], ["{,1}", "{,1}"], ["[\\b]", "\b"],
             ["\\c1", "\\c1"], ["\\1(a)", "a"], ["\\2(a)(b)", "ab"], ["\\3(a)(b)", "\x03ab"], ["(a)\\10", "a\x08"],
             ["\\1", "\x01"]];
for (var [p, s] of cases) {
  var r;
  try { r = String(new RegExp(p).test(s)); } catch (e) { r = e.constructor.name; }
  print(JSON.stringify(p) + " on " + JSON.stringify(s) + ": " + r);
}

--> a comment: the first line is an HTMLCloseComment input element (B.1.1)
// With B.1.1 the line above is a comment; under §5.1.2 alone it would be a token no production has.
if (typeof print === "undefined") globalThis.print = console.log;
print("parsed");

// AllocateSharedArrayBuffer step 9.c stores the length with SetValueInBuffer(_byteLengthBlock_, …), passing a
// Shared Data Block where SetValueInBuffer takes an ArrayBuffer or SharedArrayBuffer.
if (typeof print === "undefined") globalThis.print = console.log;
var sab = new SharedArrayBuffer(4, { maxByteLength: 16 });
print(sab.growable + " " + sab.byteLength + " " + sab.maxByteLength);
sab.grow(8);
print(sab.byteLength + " " + new Int32Array(sab).length);

// ExpressionStatement's [lookahead ∉ { let [ }] and a semicolon that §12.10 inserts before `[`: whether the
// lookahead reads the inserted `;`. Each source is parsed (not run) as a function body in a Script.
if (typeof print === "undefined") globalThis.print = console.log;
var sources = ["if (false) let\n[a] = 0;", "while (false) let\n[a] = 0;", "if (false) let\n{}",
               "if (false) let;\n[a] = 0;"];
for (var s of sources) {
  try { (0, eval)("(function () {\n" + s + "\n})"); print(JSON.stringify(s) + ": no error"); }
  catch (e) { print(JSON.stringify(s) + ": " + e.constructor.name); }
}

// FinalizationRegistry.prototype.unregister step 5 removes cells from the List its For each iterates.
if (typeof print === "undefined") globalThis.print = console.log;
var fr = new FinalizationRegistry(function () {});
var token = {}, t1 = {}, t2 = {}, t3 = {};
fr.register(t1, 1, token);
fr.register(t2, 2, token);
fr.register(t3, 3, {});
print(fr.unregister(token));
print(fr.unregister(token));

"use strict";
// IsInTailPosition: the call in `return (paren(n - 1))` lies in the ParenthesizedExpression that the cover
// covers, which §5.1.4 parses as a separate tree containing no FunctionBody.
if (typeof print === "undefined") globalThis.print = console.log;
function plain(n) { if (n === 0) return "done"; return plain(n - 1); }
function paren(n) { if (n === 0) return "done"; return (paren(n - 1)); }
for (var [name, fn] of [["plain", plain], ["paren", paren]]) {
  try { print(name + ": " + fn(100000)); }
  catch (e) { print(name + ": " + e.constructor.name); }
}
